pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }
    function testFuzz_property(uint256 deposit, address recipient) public {
        deposit = bound(deposit, 0, 1 ether);
        vm.assume(recipient != address(0));

        vm.deal(address(this), deposit + 1);
        if (deposit > 0) {
            (bool s,) = address(c).call{value: deposit}("");
            require(s);
        }

        bool ok;
        try c.withdrawAll(recipient) {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            assertTrue(address(c).balance == 0);
        } else {
            assertTrue(true);
        }
    }
}
